const ja={headline:'Microsoft 365 のURLを、使える情報に。',intro:'URLを貼り付けて、識別子・保存先・ファイルパスを確認。Power Automateの設定にも。',help:'ヘルプ',settings:'認証設定',input:'解析するURL',local:'基本解析は認証不要',analyze:'URLを解析',paste:'貼り付け',clear:'クリア',graph:'Microsoft 365 詳細情報取得',privacy:'基本解析はこのブラウザ内で処理します。詳細照会時のみMicrosoftにURLを送信します。',results:'解析結果',copyAll:'一括コピー',copy:'コピー',copied:'コピーしました',free:'無料 · 基本解析はブラウザ内で処理',step1:'URLを貼り付ける',step1text:'Teams・SharePoint・OneDriveのリンクを、そのまま入力。',step2:'識別子とパスを確認',step2text:'URLから抽出した値と、Graphで確認した値を区別して表示します。',step3:'Power Automateで利用',step3text:'必要な値をコピー。ファイル識別子の違いも確認できます。',apply:'設定を適用',save:'設定を保存',reset:'デフォルトに戻す',forget:'保存設定を削除',appGuide:'Entra ID アプリ登録ガイド',source:'ソースコード（GitHub）',webNote:'現在の認証方式：SPA / PKCE。Web認証は利用できません。',clientId:'Application (Client) ID',tenantId:'Directory (Tenant) ID',mode:'認証モード',redirectUri:'Redirect URI',platform:'Redirect URIの種類',multi:'マルチテナント',single:'シングルテナント',basic:'基本情報',teams:'Teams',files:'SharePoint / OneDrive',paths:'実ファイルパス',automate:'Power Automate',graphTab:'Microsoft Graph',json:'JSON',urlSource:'URLから抽出 · 未確認',graphSource:'Graphで確認済み',empty:'このタブで表示できる情報はありません。',ready:'基本解析が完了しました。URLの値は存在・アクセス権を確認していません。',sso:'既存Microsoft 365サインイン状態を確認中',signin:'Microsoft 365サインインが必要です',loading:'Microsoft Graphで情報を取得中',done:'取得完了。サイト側の認証キャッシュを破棄しました。',unsupported:'このURLのGraph照会は対応していません。個人用OneDriveは基本解析のみです。',url:'有効なHTTP/HTTPS URLを入力してください。',length:'URLが長すぎます。',client:'Client IDはGUID形式で入力してください。',tenant:'シングルテナントにはGUID形式のTenant IDが必要です。',redirect:'Redirect URIには現在のサイトと同じオリジンのルートURL（/）を指定してください。HTTPSまたはlocalhostが必要です。',web:'Web認証は利用できません。SPAを選択してください。',msal:'Microsoft認証を読み込めませんでした。',settingsError:'設定を確認してください。',failed:'取得に失敗しました。Microsoft認証設定、同意、アクセス権を確認してください。',401:'認証エラー。もう一度認証してください。',403:'アクセス権がありません。アクセス許可または管理者同意を確認してください。',404:'対象が見つかりません。移動・削除・共有リンクの失効も確認してください。',429:'要求制限。時間をおいて再試行してください。',clipboard:'クリップボードを利用できません。値を選択してコピーしてください。',saved:'公開設定をこのブラウザに保存しました。',applied:'設定を適用しました。',forgot:'保存設定を削除しました。',paNote:'Graph DriveItem IDはSharePointコネクタのFile Identifierではありません。File Identifierは「パスによるファイルメタデータの取得」のIdentifier出力を使用してください。ライブラリ表示名とURL上のパスも区別してください。',permissions:'直接パス照会はSites.Read.All、共有リンク照会はFiles.ReadWrite、Teams照会はTeam.ReadBasic.AllとChannel.ReadBasic.Allを要求します。アプリ同意ポリシーにより管理者同意が必要です。',guideTitle:'Microsoft Entra IDの設定（自社テナントでソースコードを展開し運用する場合）',guideText:'アプリ登録で組織アカウントを選び、認証の「シングルページアプリケーション」にこのサイトのルートURLを登録します。Client ID、必要に応じてTenant IDを設定してください。Client Secretは不要です。認証モードの切替では、登録アプリの対応アカウント設定は変更されません。',authHelp:'AADSTS50011はRedirect URIの不一致、AADSTS700016はClient IDまたはテナントの不一致が主な原因です。MFAや条件付きアクセスにはMicrosoftの案内に従ってください。Cookie制限時はポップアップでサインインします。ポップアップを許可してください。',limits:'短縮URLや不透明な共有リンクの保存先は基本解析だけでは復元できません。URLから抽出したフォルダ名・ファイル名は未確認です。プライベート・共有チャネルのサイトは標準チャネルと異なる場合があります。TeamsのファイルリンクはSharePoint URLが含まれる場合にファイル照会できます。',authPrivacy:'照会後はサイト側のトークンとアカウントキャッシュを破棄します。Microsoft 365全体からはサインアウトしません。発行済みトークンの即時失効を意味するものではありません。',graphNotice:'Graph照会はMicrosoft 365組織アカウントが対象です。URLの識別子が不足する場合は、SharePointの直接リンクまたは共有リンクを入力してください。'};
const en={headline:'Turn Microsoft 365 URLs into useful details.',intro:'Find identifiers, locations and file paths. Copy the values you need for Power Automate.',help:'Help',settings:'Authentication settings',input:'URL to analyze',local:'No sign-in for basic analysis',analyze:'Analyze URL',paste:'Paste',clear:'Clear',graph:'Get Microsoft 365 details',privacy:'Basic analysis stays in your browser. A detailed lookup sends the URL only to Microsoft.',results:'Analysis results',copyAll:'Copy all',copy:'Copy',copied:'Copied',free:'Free · Basic analysis runs in your browser',step1:'Paste a URL',step1text:'Enter a link from Teams, SharePoint or OneDrive.',step2:'Inspect identifiers and paths',step2text:'URL values and Graph-confirmed values are clearly distinguished.',step3:'Use in Power Automate',step3text:'Copy the values you need and check which identifier each action requires.',apply:'Apply settings',save:'Save settings',reset:'Restore defaults',forget:'Delete saved settings',appGuide:'Entra ID app registration guide',source:'Source code (GitHub)',webNote:'Current authentication: SPA / PKCE. Web authentication is unavailable.',clientId:'Application (Client) ID',tenantId:'Directory (Tenant) ID',mode:'Authentication mode',redirectUri:'Redirect URI',platform:'Redirect URI platform',multi:'Multitenant',single:'Single tenant',basic:'Basic information',teams:'Teams',files:'SharePoint / OneDrive',paths:'Actual file paths',automate:'Power Automate',graphTab:'Microsoft Graph',json:'JSON',urlSource:'Extracted from URL · Unverified',graphSource:'Confirmed by Graph',empty:'No information is available in this tab.',ready:'Basic analysis complete. URL values do not confirm existence or access.',sso:'Checking existing Microsoft 365 sign-in',signin:'Microsoft 365 sign-in required',loading:'Retrieving Microsoft Graph information',done:'Lookup complete. This site’s authentication cache was cleared.',unsupported:'Graph lookup is unavailable for this URL. Personal OneDrive supports basic analysis only.',url:'Enter a valid HTTP/HTTPS URL.',length:'The URL is too long.',client:'Enter a GUID for Client ID.',tenant:'Single tenant mode requires a Tenant ID GUID.',redirect:'Use the current site origin with root path (/), over HTTPS or localhost.',web:'Web authentication is unavailable. Select SPA.',msal:'Microsoft authentication could not be loaded.',settingsError:'Check the settings.',failed:'Lookup failed. Check Microsoft authentication settings, consent and access.',401:'Authentication failed. Sign in again.',403:'Access denied. Check permissions and administrator consent.',404:'Resource not found. Check for moves, deletion or an expired link.',429:'Rate limited. Try again later.',clipboard:'Clipboard unavailable. Select the value and copy it manually.',saved:'Public settings saved in this browser.',applied:'Settings applied.',forgot:'Saved settings deleted.',paNote:'A Graph DriveItem ID is not a SharePoint connector File Identifier. Use the Identifier output of Get file metadata using path. Distinguish the library display name from its URL path.',permissions:'Direct paths request Sites.Read.All. Sharing links request Files.ReadWrite. Teams requests Team.ReadBasic.All and Channel.ReadBasic.All. Consent policies may require administrator approval.',guideTitle:'Configure Microsoft Entra ID (when deploying and operating the source code in your own tenant)',guideText:'Register an application for organizational accounts. Under Authentication, add this site’s root URL as a Single-page application redirect URI. Set Client ID and, when needed, Tenant ID. No Client Secret is needed. Changing the mode here does not change the registered app’s supported account types.',authHelp:'AADSTS50011 usually indicates a redirect URI mismatch. AADSTS700016 usually indicates an incorrect Client ID or tenant. Follow Microsoft prompts for MFA and conditional access. Allow pop-ups when cookies prevent silent sign-in.',limits:'Short links and opaque sharing links cannot reveal file locations through basic analysis alone. Names extracted from URLs are unverified. Private and shared channels can use different SharePoint sites. Teams file lookup requires an embedded SharePoint URL.',authPrivacy:'After lookup, the site clears its token and account cache. Your Microsoft 365 sign-in remains active. Clearing the cache does not immediately revoke issued tokens.',graphNotice:'Graph lookup supports Microsoft 365 organizational accounts. If the URL lacks identifiers, enter a direct SharePoint link or sharing link.'};
